mapper.select:
SELECT s.id AS spot_id, s.name AS name, ST_Distance_Sphere(s.location, ST_SRID(POINT(#{dup.centerLng}, #{dup.centerLat}), 4326)) AS distance_meters FROM spot s WHERE s.type = 'BAKJI' AND s.status = 'ACTIVE' AND MBRIntersects( ST_SRID( POLYGON(LINESTRING( POINT(#{dup.swLng}, #{dup.swLat}), POINT(#{dup.neLng}, #{dup.swLat}), POINT(#{dup.neLng}, #{dup.neLat}), POINT(#{dup.swLng}, #{dup.neLat}), POINT(#{dup.swLng}, #{dup.swLat}))), 4326), s.location) AND ST_Distance_Sphere(s.location, ST_SRID(POINT(#{dup.centerLng}, #{dup.centerLat}), 4326)) <= #{dup.radiusMeters}
AND s.id <> #{dup.excludeSpotId}
ORDER BY distance_meters, s.id LIMIT #{dup.limit}
